#!/bin/bash
set -eo pipefail
umask 077
ROOT=/data1/home/sunyiq/china_input_completion_hpc_20261015_001/soil_pair_v1
test ! -e "$ROOT"
test ! -L "$ROOT"
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_DEPLOY'
import base64,hashlib,io,json,pathlib,zipfile
root=pathlib.Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/soil_pair_v1')
assert not root.exists() and not root.is_symlink() and root.parent.resolve(strict=True)==root.parent
root.mkdir(mode=0o700)
(root/'logs').mkdir(mode=0o700)
raw=base64.b64decode('',validate=True)
assert len(raw)==126921 and hashlib.sha256(raw).hexdigest()=='05c5cca4720ecb0075c35ebebac8f762a636f76d16b74f1d9821506242014f0e'
expected=json.loads('{"main/NUMERICAL_CONTRACT.json":{"bytes":246425,"sha256":"151625743f8541f623fd607618404e81c0162c697ac65c9be112b151d4013cc4"},"main/soil_remaining_main.py":{"bytes":12609,"sha256":"3827d309c2ea5a023efcf1755dc497522cdf587f4ea18590f8b5ec9e4fa326e6"},"independent/soil_remaining_independent.py":{"bytes":18568,"sha256":"868c74d3cb20495f2715f46befcf8961b1fb06d9054745d23209bc838b1226d3"},"run_soil_pair.py":{"bytes":6749,"sha256":"9c64b3d020985220bf722a37bd33ea96ce3b0f790ef3428bf5137a15c83aa544"},"vegetation_probe/probe_vegetation_source.py":{"bytes":6219,"sha256":"eef18d574c0013ed0bd90e80c33ac196d606032bf2dce41b56e5ec6100c3bfe0"},"vegetation_probe/FACTORY_METADATA.xml":{"bytes":4560,"sha256":"18adab0dc2cbd6428c0cd1b94980c7aeeec02fe93fd538e052638ee55998403c"},"INDEPENDENT_TEMPLATE.json":{"bytes":1003,"sha256":"f55c91f435633a1900e9ee8e28162ab89f0d92f6e4e1ae4b8c721db398ae8bfb"},"PAIR_CONTRACT.json":{"bytes":2619,"sha256":"4a80f581b4e9029cbf3e937ef8b07846c341bfafd0ad27b9b8e95c91e49a4a0a"}}')
with zipfile.ZipFile(io.BytesIO(raw)) as archive:
 assert archive.namelist()==sorted(expected) and len(archive.namelist())==len(set(archive.namelist()))
 assert sum(item.file_size for item in archive.infolist())<=4194304
 for name in archive.namelist():
  parts=pathlib.PurePosixPath(name).parts
  assert 1<=len(parts)<=2 and all(p not in ('','.', '..') for p in parts) and not name.startswith('/')
  data=archive.read(name)
  assert len(data)==expected[name]['bytes'] and hashlib.sha256(data).hexdigest()==expected[name]['sha256']
  target=root/name
  target.parent.mkdir(exist_ok=True)
  with target.open('xb') as stream:stream.write(data)
job=base64.b64decode('',validate=True)
with (root/'soil.sbatch').open('xb') as stream:stream.write(job)
print('OWN_SOIL_PAIR_PAYLOAD_VERIFIED='+str(len(expected)))
PY_DEPLOY
cd "$ROOT"
test ! -e SUBMISSION_STARTED
test ! -e OWN_SOIL_PAIR_JOB_ID
set -o noclobber
printf 'ONE_SUBMISSION_ONLY\n' > SUBMISSION_STARTED
set +e
output=$(sbatch soil.sbatch 2>&1)
code=$?
set -e
printf '%s\n' "$output"
printf 'OWN_SOIL_PAIR_SUBMIT_EXIT=%s\n' "$code"
test "$code" = 0
job=$(printf '%s\n' "$output" | sed -n 's/^Submitted batch job \([0-9][0-9]*\)$/\1/p')
test -n "$job"
test "$(printf '%s\n' "$job" | wc -l)" = 1
printf '%s\n' "$job" > OWN_SOIL_PAIR_JOB_ID
printf 'OWN_SOIL_PAIR_JOB_ID=%s\n' "$job"
printf 'OWN_SOIL_PAIR_SUBMIT_DONE\n'
